// İki webhook da buradan geçer. Başlıklar maskelenir, gövde kırpılır.
const j = $input.first().json || {};

let yontem = String(j.method || '').toUpperCase();
if (!yontem) {
  try { yontem = $('İstek Yakala (GET)').first() ? 'GET' : 'POST'; } catch (e) { yontem = 'POST'; }
}

const basliklar = j.headers || {};
const sorgu = j.query || {};

// Gizli bilgi taşıyan başlıklar telefona düşmesin diye maskelenir.
const GIZLI = /^(authorization|proxy-authorization|cookie|set-cookie|x-api-key|x-auth-token)$/i;
const gizliGibi = /(token|secret|password|api[-_]?key|signature|imza)/i;
const maske = (deger) => {
  const s = String(deger);
  return s.length <= 6 ? '***' : s.slice(0, 6) + '… (' + s.length + ' karakter, gizlendi)';
};
const temizBasliklar = {};
let sayac = 0;
for (const [ad, deger] of Object.entries(basliklar)) {
  if (sayac++ >= 40) break;
  temizBasliklar[ad] = (GIZLI.test(ad) || gizliGibi.test(ad)) ? maske(deger) : String(deger).slice(0, 300);
}

const hamGovde = j.body;
let govde = '';
let govdeTipi = 'yok';
if (typeof hamGovde === 'string') {
  govde = hamGovde;
  govdeTipi = 'metin';
} else if (hamGovde && typeof hamGovde === 'object' && Object.keys(hamGovde).length) {
  govde = JSON.stringify(hamGovde, null, 2);
  govdeTipi = 'json';
}
const boyut = govde.length;
if (govde.length > 4000) govde = govde.slice(0, 4000) + '\n… (kırpıldı)';

const kod = Math.min(599, Math.max(100, Number(sorgu.kod) || 200));

return [{ json: {
  yontem,
  etiket: String(sorgu.etiket || '').slice(0, 40),
  sorgu,
  basliklar: temizBasliklar,
  govde,
  govdeTipi,
  boyut,
  kod,
  ip: String(basliklar['x-forwarded-for'] || basliklar['x-real-ip'] || '').split(',')[0].trim(),
  icerikTipi: String(basliklar['content-type'] || ''),
} }];

// Yakalanan isteği listeye ekler (son 50 tutulur).
// Okuma zinciri hata verdiyse: dosya bozuk/erişilemez ise çalışma durdurulur —
// aksi hâlde liste boş sanılıp üzerine yazılır ve eski kayıtlar kaybolur.
const okuHata = $('Yakalananları Oku').first().json.error;
const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
const dosyaYok = /ENOENT|no such file|not found/i.test(okuMesaj);
const cikarHata = $('Yakalananları Çıkar').first().json.error;
if (!dosyaYok && (okuHata || cikarHata)) {
  const m = okuMesaj || String((cikarHata && cikarHata.message) || cikarHata);
  throw new Error('yakalanan-istekler.json okunamadı; veri kaybını önlemek için durduruldu → ' + m);
}

const gelen = $('Gelen İsteği Al').first().json;
const okunan = $input.first().json || {};
const ham = (okunan.data && okunan.data.istekler) || okunan.istekler || [];
const oncekiler = Array.isArray(ham) ? ham : [];

const id = oncekiler.reduce((mx, x) => Math.max(mx, Number(x.id) || 0), 0) + 1;
const kayit = {
  id,
  zaman: new Date().toISOString(),
  yontem: gelen.yontem,
  etiket: gelen.etiket,
  icerikTipi: gelen.icerikTipi,
  sorgu: gelen.sorgu,
  basliklar: gelen.basliklar,
  govdeTipi: gelen.govdeTipi,
  boyut: gelen.boyut,
  govde: gelen.govde,
  ip: gelen.ip,
};

const istekler = [...oncekiler, kayit].slice(-50);
return [{ json: { istekler, kayit, id, kod: gelen.kod, yazilsin: true } }];

// Dosyaya yalnızca istek listesi yazılır.
const j = $input.first().json;
if (!j.yazilsin) return [];
return [{ json: { istekler: j.istekler } }];

// GET /webhook/istekler — yakalananları JSON olarak verir.
//   ?adet=5   → son 5 kayıt (varsayılan 10)
//   ?id=3     → tek kayıt (tüm ayrıntısıyla)
//   ?etiket=stripe → yalnızca o etiketli kayıtlar
const sorgu = $('İstek Listesi (Webhook GET)').first().json.query || {};
const okuHata = $('Yakalananları Oku (Liste)').first().json.error;
const cikarHata = $('Yakalananları Çıkar (Liste)').first().json.error;
if (okuHata || cikarHata) {
  const m = String((okuHata && (okuHata.message || okuHata)) || (cikarHata && (cikarHata.message || cikarHata)));
  return [{ json: { govde: { hata: /ENOENT|no such file/i.test(m)
    ? 'yakalanan-istekler.json yok — cp local-files/yakalanan-istekler.ornek.json local-files/yakalanan-istekler.json'
    : 'yakalanan-istekler.json okunamadı: ' + m } } }];
}

const j = $input.first().json || {};
const ham = (j.data && j.data.istekler) || j.istekler || [];
const istekler = Array.isArray(ham) ? ham : [];

const id = Number(sorgu.id) || 0;
if (id) {
  const k = istekler.find((x) => Number(x.id) === id);
  return [{ json: { govde: k || { hata: '#' + id + ' bulunamadı' } } }];
}

const etiket = String(sorgu.etiket || '').trim();
const adet = Math.min(50, Math.max(1, Number(sorgu.adet) || 10));
const suzulmus = etiket ? istekler.filter((x) => String(x.etiket || '') === etiket) : istekler;
return [{ json: { govde: suzulmus.slice(-adet).reverse() } }];

// Telegram komutları: /istekler (son 5) · /istek <no> (ayrıntı) · /istektemizle
const cagri = $('Workflow 05\'ten Çağrı (İstek)').first().json || {};
const chat = cagri.chat_id ? String(cagri.chat_id) : '';
if (!chat) return [];

const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const okuHata = $('Yakalananları Oku (Rapor)').first().json.error;
const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
const cikarHata = $('Yakalananları Çıkar (Rapor)').first().json.error;
if (okuHata || cikarHata) {
  const dosyaYok = /ENOENT|no such file|not found/i.test(okuMesaj);
  return [{ json: { chat_id: chat, yazilsin: false, istekler: [], text: dosyaYok
    ? '🪤 Henüz istek yakalanmadı. Kurulum: cp local-files/yakalanan-istekler.ornek.json local-files/yakalanan-istekler.json'
    : '🪤 yakalanan-istekler.json okunamadı: ' + (okuMesaj || 'bozuk dosya') } }];
}

const j = $input.first().json || {};
const ham = (j.data && j.data.istekler) || j.istekler || [];
const istekler = Array.isArray(ham) ? ham : [];
const komut = String(cagri.komut || 'liste').toLowerCase();
const saat = (iso) => {
  const d = new Date(iso);
  return isNaN(d.getTime()) ? '??:??' : d.toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' });
};

if (komut === 'temizle') {
  return [{ json: {
    chat_id: chat,
    yazilsin: true,
    istekler: [],
    text: '🪤 ' + istekler.length + ' kayıt silindi. Yakalayıcı boş.',
  } }];
}

if (komut === 'detay') {
  const id = Number(cagri.id) || 0;
  const k = istekler.find((x) => Number(x.id) === id);
  if (!k) {
    return [{ json: { chat_id: chat, yazilsin: false, istekler, text: '#' + id + ' bulunamadı. /istekler ile bakın.' } }];
  }
  const basliklar = Object.entries(k.basliklar || {}).map(([a, d]) => a + ': ' + d).join('\n');
  const sorgu = Object.entries(k.sorgu || {}).map(([a, d]) => a + '=' + d).join('&');
  const govde = k.govde || '(gövde yok)';
  const metin = [
    '#' + k.id + ' ' + k.yontem + (k.etiket ? ' [' + k.etiket + ']' : '') + ' — ' + saat(k.zaman),
    sorgu ? 'Sorgu: ' + sorgu : '',
    k.ip ? 'IP: ' + k.ip : '',
    '',
    'Başlıklar:',
    basliklar || '(yok)',
    '',
    'Gövde (' + k.govdeTipi + ', ' + k.boyut + ' karakter):',
    govde,
  ].filter((x) => x !== '').join('\n');
  return [{ json: { chat_id: chat, yazilsin: false, istekler, text: '<pre>' + esc(metin.slice(0, 3500)) + '</pre>' } }];
}

if (istekler.length === 0) {
  return [{ json: { chat_id: chat, yazilsin: false, istekler, text:
    '🪤 Henüz istek yakalanmadı.\nTest için: curl -X POST http://localhost:5678/webhook/yakala -d \'{"a":1}\'' } }];
}
const son = istekler.slice(-5).reverse();
const satirlar = son.map((k) => '#' + k.id + ' ' + saat(k.zaman) + ' ' + k.yontem +
  (k.etiket ? ' [' + k.etiket + ']' : '') + ' — ' + k.govdeTipi + ', ' + k.boyut + ' karakter');
return [{ json: {
  chat_id: chat,
  yazilsin: false,
  istekler,
  text: esc('🪤 Son ' + son.length + ' istek (toplam ' + istekler.length + '):\n' + satirlar.join('\n') +
    '\n\nAyrıntı için: /istek <numara>'),
} }];

// Dosyaya yalnızca istek listesi yazılır.
const j = $input.first().json;
if (!j.yazilsin) return [];
return [{ json: { istekler: j.istekler } }];
